sys_script_client.script:
//MSSCUSTODY - 7266

function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var outcome = g_form.getValue('outcome');
    var ownBusiness = g_scratchpad.ownB;

    if (isLoading || newValue === '') {
        //console.log("log1");
        //g_form.setMandatory('amend_counterparty_code_ref', false);
        g_form.setDisplay('amend_counterparty_code_ref', false);
        g_form.setDisplay('switch_counterparty_code', false);

        g_form.setMandatory('transaction_reference', false);
        g_form.setDisplay('transaction_reference', false);

        g_form.setMandatory('transaction_reference_link', false);
        g_form.setDisplay('transaction_reference_link', false);

        g_form.setDisplay('trade_link_reference', false);

        hideInitialFields();

        var tradeTaskType = g_scratchpad.blkTskRelated;
        var taskState = g_form.getValue('state').toString();

        if ((tradeTaskType == 'Maker') && ((taskState == '1') || (taskState == '2'))) {
            //console.log("log2");
            hideInitialFields();
            //g_form.setMandatory('sub_outcome', false);
            //g_form.setDisplay('sub_outcome', false);

            g_form.setMandatory('transaction_reference', false);
            g_form.setDisplay('transaction_reference', false);

            //g_form.setMandatory('amend_counterparty_code_ref', false);
            g_form.setDisplay('amend_counterparty_code_ref', false);
            g_form.setDisplay('switch_counterparty_code', false);

        } else if ((tradeTaskType == 'Checker') || (tradeTaskType == 'Maker') || (tradeTaskType.indexOf('GHSS') > -1) || (taskState == 4) || (taskState == 3)) {
            showFieldsForChecker();
        }
        return;

    } else {
        //console.log("log3");
        if (newValue == 'Pair Trade' && outcome == 'Switch Maintenance') {
            showPairTradeFields();

        } else if (newValue == 'Convert to Non-Switching Trade' && outcome == 'Switch Maintenance') {
            showNonSwitchFields();

        } else if (newValue == 'De-Pair Trade' && outcome == 'Switch Maintenance') {
            showDepairFields();

        } else if (newValue == 'Link Trade' && outcome == 'Linking') {
            showLinkTradeFields();
        } else if (outcome == 'Linking' && g_form.getValue('sub_outcome') == 'De-Link Trades') { //MSSCUSTODY-8162
            showDeLinkFields();
        } else if (outcome == 'Linking' && g_form.getValue('sub_outcome') == 'Self De-Link Trade') { //MSSCUSTODY-8162
            showDeLinkFields();
        } else {
            g_form.setMandatory('transaction_reference', false);
            g_form.setMandatory('transaction_reference_link', false);
            g_form.setMandatory('amend_counterparty_code_ref', false);
            g_form.setDisplay('amend_script_hold_indicator', false);
            hideInitialFields();
        }

    }

    //------------------Functions----------------------------------------

    function hideInitialFields() {
        var fieldsToHide = getFieldsToHide();
        fieldsToHide.forEach(function(field) {
            g_form.setDisplay(field, false);
            //g_form.clearValue(field);
        });
    }

    function getFieldsToHide() {
        return [
            'transaction_reference',
            'transaction_type_display',
            'legacy_status_display',

            'amend_counterparty_code_ref',
            'switch_counterparty_code',

            'pair_switch_reference',

            'transaction_reference_link',
            'amend_gdi_indicator',
            'amend_cash_hold_indicator',
            'settle_link',
            'amend_script_hold_indicator',
            'trade_link_reference', //MSSCUSTODY-8162
            'd_transaction_reference',
            'd_legacy_status',
            'd_hold_indicator',
            'd_transaction_type',
            'd_settlement_quantity', //MSSCUSTODY-8162
            'script_hold_indicator'
        ];
    }

    function showPairTradeFields() {
        g_form.setDisplay('transaction_reference', true);
        g_form.setMandatory('transaction_reference', true);

        g_form.setDisplay('transaction_type_display', true);
        g_form.setReadOnly('transaction_type_display', true);
        g_form.setDisplay('legacy_status_display', true);
        g_form.setReadOnly('legacy_status_display', true);

        //g_form.setMandatory('amend_counterparty_code_ref', false);
        g_form.setDisplay('amend_counterparty_code_ref', false);
        g_form.setDisplay('switch_counterparty_code', false);
    }

    function showNonSwitchFields() {
        g_form.setDisplay('amend_counterparty_code_ref', true);

        g_form.setDisplay('switch_counterparty_code', true);
        g_form.setReadOnly('switch_counterparty_code', true);

        g_form.setMandatory('transaction_reference', false);
        g_form.setDisplay('transaction_reference', false);

        g_form.setDisplay('transaction_type_display', false);
        g_form.setDisplay('legacy_status_display', false);

    }

    function showDepairFields() {
        g_form.setDisplay('pair_switch_reference', true);
        showSwitchRefValue();
        g_form.setReadOnly('pair_switch_reference', true);

    }


    function showSwitchRefValue() {
        var ga1 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        ga1.addParam('sysparm_name', 'getSwitchReferenceValue');
        ga1.addParam('sysparm_sys_id', g_form.getUniqueValue());
        ga1.getXMLAnswer(function(response) {
            var switchRefVal = response;
            g_form.setValue('pair_switch_reference', switchRefVal);
            g_form.setReadOnly('pair_switch_reference', true);
        });
    }

    function showLinkTradeFields() {
        g_form.clearValue('transaction_reference_link');
        g_form.setDisplay('transaction_reference_link', true);
        g_form.setMandatory('transaction_reference_link', true);

        g_form.setDisplay('amend_script_hold_indicator', true);
        g_form.setReadOnly('amend_script_hold_indicator', true);
        g_form.setLabelOf('amend_script_hold_indicator', 'Scrip Hold Indicator (Pairing Trade)');


        if (ownBusiness != 'DCC HK') {
            g_form.clearValue('amend_gdi_indicator');
            g_form.setDisplay('amend_gdi_indicator', true);
            g_form.setMandatory('amend_gdi_indicator', true);

            g_form.clearOptions('amend_gdi_indicator');
            g_form.addOption('amend_gdi_indicator', '', '--None--');
            g_form.addOption('amend_gdi_indicator', 'Auto Generation', 'Auto Generation');
            g_form.addOption('amend_gdi_indicator', 'Manual Generation', 'Manual Generation');
            g_form.addOption('amend_gdi_indicator', 'Not Generate', 'Not Generate');
        } else {
            g_form.setDisplay('amend_gdi_indicator', false);
            //g_form.clearValue('amend_gdi_indicator');
        }
        g_form.clearValue('amend_cash_hold_indicator');
        g_form.setDisplay('amend_cash_hold_indicator', true);
        g_form.setMandatory('amend_cash_hold_indicator', true);
        g_form.setLabelOf('amend_cash_hold_indicator', 'Hold Indicator');
        g_form.setValue('amend_cash_hold_indicator', 'N');

        g_form.setDisplay('script_hold_indicator', true);
        g_form.setReadOnly('script_hold_indicator', true);
        var gajaxScrip = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        gajaxScrip.addParam("sysparm_name", "getScriptHoldValue");
        gajaxScrip.addParam("sysparm_tradRef", g_form.getValue('trade_transaction_reference'));
        gajaxScrip.addParam("sysparm_txnType", g_form.getValue('trade_transaction_type'));
        gajaxScrip.addParam("sysparm_legStatus", g_form.getValue('trade_legacy_status'));
        gajaxScrip.getXMLAnswer(function(response) {
            g_form.setValue('script_hold_indicator', response);
        });

        g_form.clearValue('settle_link');
        g_form.setDisplay('settle_link', true);

    }

    function showDeLinkFields() { //MSSCUSTODY-8162
        var bulkId = g_form.getUniqueValue();
        if (!bulkId) return;

        if (g_form.getValue('sub_outcome') === 'De-Link Trades') {
            g_form.setDisplay('trade_link_reference', true);
            g_form.setDisplay('d_transaction_reference', true);
            g_form.setDisplay('d_transaction_type', false);
            g_form.setDisplay('d_settlement_quantity', false);
            g_form.setDisplay('d_legacy_status', false);
            g_form.setDisplay('d_hold_indicator', false);

            g_form.setReadOnly('trade_link_reference', true);
            // g_form.setReadOnly('d_transaction_reference', true);
            g_form.setReadOnly('d_transaction_type', true);
            g_form.setReadOnly('d_settlement_quantity', true);
            g_form.setReadOnly('d_legacy_status', true);
            g_form.setReadOnly('d_hold_indicator', true);

            //MSSCUSTODY-8300
            g_form.setMandatory('transaction_reference_link', false);
            g_form.setDisplay('transaction_reference_link', false);
            g_form.setDisplay('amend_script_hold_indicator', false);
            g_form.setDisplay('amend_gdi_indicator', false);
            g_form.setDisplay('amend_cash_hold_indicator', false);
            g_form.setDisplay('settle_link', false);

        } else {
            g_form.setDisplay('script_hold_indicator', true);
            g_form.setReadOnly('script_hold_indicator', true);
            var gajaxScrip = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
            gajaxScrip.addParam("sysparm_name", "getScriptHoldValue");
            gajaxScrip.addParam("sysparm_tradRef", g_form.getValue('trade_transaction_reference'));
            gajaxScrip.addParam("sysparm_txnType", g_form.getValue('trade_transaction_type'));
            gajaxScrip.addParam("sysparm_legStatus", g_form.getValue('trade_legacy_status'));
            gajaxScrip.getXMLAnswer(function(response) {
                g_form.setValue('script_hold_indicator', response);
            });

            //MSSCUSTODY-8300
            g_form.setMandatory('transaction_reference_link', false);
            g_form.setDisplay('transaction_reference_link', false);
            g_form.setDisplay('amend_script_hold_indicator', false);
            g_form.setDisplay('amend_gdi_indicator', false);
            g_form.setDisplay('amend_cash_hold_indicator', false);
            g_form.setDisplay('settle_link', false);
        }
        var gajax = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        gajax.addParam('sysparm_name', 'getTradeDetailsDeLink');
        gajax.addParam('sysparm_bulk_id', g_form.getUniqueValue());
        gajax.getXMLAnswer(function(response) {
            if (response) {
                var trade = JSON.parse(response);
                g_form.setValue('trade_link_reference', trade.link_reference);
                // // g_form.setValue('d_transaction_reference', trade.transaction_reference);
                // g_form.setValue('d_transaction_type', trade.transaction_type);
                // g_form.setValue('d_settlement_quantity', trade.settlement_quantity);
                // g_form.setValue('d_legacy_status', trade.legacy_status);
                // g_form.setValue('d_hold_indicator', trade.hold_indicator);
            } else {
                g_form.setValue('trade_link_reference', '');
            }
        });
        var ga = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkTradeUtils');
        ga.addParam('sysparm_name', 'getTradesDeLinkField');
        ga.addParam('sysparm_bulkSysId', bulkId);
        ga.getXMLAnswer(function(response) {
            if (response) {
                // var trade = JSON.parse(response);
                // g_form.setValue('trade_link_reference', trade.link_reference);
                // // g_form.setValue('d_transaction_reference', trade.transaction_reference);
                // g_form.setValue('d_transaction_type', trade.transaction_type);
                // g_form.setValue('d_settlement_quantity', trade.settlement_quantity);
                // g_form.setValue('d_legacy_status', trade.legacy_status);
                // g_form.setValue('d_hold_indicator', trade.hold_indicator);
                var sysIds = response.split(',');
                g_form.setValue('d_transaction_reference', sysIds.join(','));

            } else {
                g_form.setValue('d_transaction_reference', '');
            }
        });
    }

    function showFieldsForChecker() {
        var selectedSubOutcome = g_form.getValue('sub_outcome');

        var pairTrade = ['transaction_reference', 'transaction_type_display', 'legacy_status_display'];
        if (selectedSubOutcome == 'Pair Trade') {
            for (var i = 0; i < pairTrade.length; i++) {
                g_form.setDisplay(pairTrade[i], true);
                g_form.setReadOnly(pairTrade[i], true);
            }

        } else if (selectedSubOutcome == 'Convert to Non-Switching Trade') {
            g_form.setDisplay('amend_counterparty_code_ref', false);
            g_form.setReadOnly('amend_counterparty_code_ref', false);

            for (var i = 0; i < pairTrade.length; i++) {
                g_form.setDisplay(pairTrade[i], false);
                g_form.setReadOnly(pairTrade[i], false);
            }

            g_form.setDisplay('switch_counterparty_code', true);
            g_form.setReadOnly('switch_counterparty_code', true);

        } else if (selectedSubOutcome == 'De-Pair Trade') {
            g_form.setDisplay('pair_switch_reference', true);
            g_form.setReadOnly('pair_switch_reference', true);

        } else if (selectedSubOutcome == 'Link Trade') {
            var linkTrade = ['transaction_reference_link',
                'amend_gdi_indicator',
                'amend_cash_hold_indicator',
                'settle_link'
            ];

            for (var i = 0; i < linkTrade.length; i++) {
                g_form.setDisplay(linkTrade[i], true);
                g_form.setReadOnly(linkTrade[i], true);
            }

            if (ownBusiness != 'DCC HK') {
                g_form.setDisplay('amend_gdi_indicator', true);
                g_form.setReadOnly('amend_gdi_indicator', true);

            } else {
                g_form.setDisplay('amend_gdi_indicator', false);
            }

        } else if (selectedSubOutcome == 'De-Link Trades') {
            var deLinkTrade = ['trade_link_reference', 'd_transaction_reference' /*, 'd_transaction_type', 'd_settlement_quantity', 'd_legacy_status', 'd_hold_indicator'*/ ];
            for (var i = 0; i < deLinkTrade.length; i++) {
                g_form.setDisplay(deLinkTrade[i], true);
                g_form.setReadOnly(deLinkTrade[i], true);
            }

        }

    }

}
